package com.airesumebuilder.feature.pdf.controller;import com.airesumebuilder.common.dto.*;import com.airesumebuilder.feature.pdf.repository.PdfExportRepository.Export;import com.airesumebuilder.feature.pdf.service.PdfService;import com.airesumebuilder.security.CurrentUser;import java.util.List;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/v1/pdf")public class PdfController{private final PdfService service;private final CurrentUser user;public PdfController(PdfService service,CurrentUser user){this.service=service;this.user=user;}@PostMapping(value="/resumes/{id}",produces=MediaType.APPLICATION_PDF_VALUE)public ResponseEntity<byte[]>generate(@PathVariable long id){var pdf=service.generate(user.email(),id);return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=\""+pdf.fileName()+"\"").contentType(MediaType.APPLICATION_PDF).contentLength(pdf.content().length).body(pdf.content());}@GetMapping("/resumes/{id}/history")public ResponseEntity<ApiResponse<List<Export>>>history(@PathVariable long id,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="100")int size){var result=service.history(user.email(),id,page,size);int pages=(int)Math.ceil(result.total()/(double)result.size());return ResponseEntity.ok(ApiResponse.paginated(result.items(),new Pagination(result.page(),result.size(),result.total(),pages)));}}
